/// Who is connecting. Used for feature gating and abuse triage, never for tracking.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ClientInfo {
    pub platform: Platform,
    pub app_version: String,
    pub os_version: Option<String>,
    pub device_model: Option<String>,
}

impl Encode for ClientInfo {
    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.enter()?;
        w.write_u32(self.platform.to_wire());
        w.write_str(&self.app_version)?;
        let present =
            usize::from(self.os_version.is_some()) + usize::from(self.device_model.is_some());
        w.write_u32(present as u32);
        if let Some(v) = &self.os_version {
            w.optional(1, |w| {
                w.write_str(v)?;
                Ok(())
            })?;
        }
        if let Some(v) = &self.device_model {
            w.optional(2, |w| {
                w.write_str(v)?;
                Ok(())
            })?;
        }
        w.leave();
        Ok(())
    }
}

impl Decode for ClientInfo {
    fn decode(r: &mut Reader) -> Result<Self> {
        r.enter()?;
        let mut out = Self::default();
        out.platform = Platform::from_wire(r.read_u32()?);
        out.app_version = r.read_string()?;
        let optional_count = r.read_u32()?;
        for _ in 0..optional_count {
            let (field_id, mut owned) = r.read_optional()?;
            let sub = &mut owned;
            match field_id {
                1 => out.os_version = Some(sub.read_string()?),
                2 => out.device_model = Some(sub.read_string()?),
                _ => { /* unknown optional field: skipped by length (forward compatibility) */ }
            }
        }
        r.leave();
        Ok(out)
    }
}

